#!/usr/bin/env node
// Fails when the FastAPI response shape for a mobile-consumed endpoint drifts
// incompatibly from src/services/api/contracts.ts. Compares the committed
// OpenAPI snapshot (docs/openapi-snapshot.json — regenerated by
// `npm run contracts:refresh`, reviewed, and committed by hand) against a
// manifest of the fields each TS interface actually declares, kept here in
// sync with contracts.ts by hand (same pattern as the backend's own
// ALLOWED_EVENTS mirror in app/api/v1/tracking.py).
//
// Usage: node scripts/verify-contracts.mjs [--root <dir>]

import { readFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { argv, exit, cwd } from 'node:process';

function getRoot() {
  const i = argv.indexOf('--root');
  return i !== -1 && argv[i + 1] ? argv[i + 1] : cwd();
}

// backendSchema: the OpenAPI component name. required: field names the
// mobile TS interface treats as always-present (must exist in the backend's
// own `required` list — if the backend ever makes one optional, that IS a
// breaking drift for code that reads it unconditionally). optional: fields
// the TS interface also knows about, whether or not the backend requires
// them. Anything in the backend schema NOT listed in required+optional is
// undeclared drift (new field our contract doesn't know about yet).
const MANIFEST = {
  UserResponse: {
    required: ['id', 'created_at', 'updated_at'],
    // onboarding_complete/onboarding_state/banned have Pydantic defaults
    // (False / "quiz_in_progress" / False), so OpenAPI doesn't mark them
    // required even though the DB always populates them — real-world
    // guarantee, not a contract one. Listed here, not in `required`.
    optional: [
      'supabase_uid', 'phone', 'display_name', 'gender', 'age', 'ncr_zone', 'max_travel_km',
      'schedule', 'onboarding_complete', 'onboarding_state', 'community_slug', 'banned',
      'terms_version', 'terms_accepted_at', 'privacy_version', 'privacy_accepted_at',
    ],
  },
  CurrentLegalResponse: {
    required: ['terms_version', 'privacy_version'],
    optional: [],
  },
  RefreshResponse: {
    required: ['access_token', 'refresh_token'],
    optional: [],
  },
  VerifyOTPResponse: {
    required: ['access_token', 'refresh_token', 'user'],
    optional: ['prior_session'],
  },
  ReauthTokenResponse: {
    required: ['reauth_token', 'expires_in'],
    optional: [],
  },
  PriorSession: {
    required: ['submission_id', 'answers'],
    optional: ['is_complete', 'status', 'last_page'],
  },
  QuizSummaryResponse: {
    required: ['submission_id', 'status'],
    // insights/tags have Pydantic list defaults (never absent, just possibly
    // empty) — real-world guarantee, not a contract one, so listed here.
    optional: [
      'name', 'headline', 'archetype', 'archetype_desc', 'share_quote',
      'spirit_animal', 'spirit_desc', 'insights', 'tags', 'share_card', 'deep_summary',
    ],
  },
  InsightItem: {
    required: ['label', 'text'],
    optional: [],
  },
  UserDeleteResponse: {
    required: ['id', 'deleted_at'],
    optional: [],
  },
  CommunityMeResponse: {
    required: ['archetype_slug', 'name', 'description', 'muted', 'joined_at'],
    optional: [],
  },
  PublicAuthor: {
    required: ['id'],
    optional: ['display_name', 'avatar_key', 'archetype_slug'],
  },
  MessageOut: {
    required: ['id', 'client_message_id', 'body', 'created_at', 'author'],
    optional: [],
  },
  MessageHistoryResponse: {
    required: ['messages'],
    optional: ['next_cursor'],
  },
  WsTicketResponse: {
    required: ['ticket'],
    optional: ['expires_in'],
  },
};

export function verifyContracts(root) {
  const errors = [];
  const snapshotPath = join(root, 'docs/openapi-snapshot.json');
  if (!existsSync(snapshotPath)) {
    return { ok: false, errors: ['missing docs/openapi-snapshot.json — run `npm run contracts:refresh` against a live backend and commit it'] };
  }

  let snapshot;
  try {
    snapshot = JSON.parse(readFileSync(snapshotPath, 'utf8'));
  } catch {
    return { ok: false, errors: ['docs/openapi-snapshot.json is not valid JSON'] };
  }

  const schemas = snapshot?.components?.schemas;
  if (!schemas) {
    return { ok: false, errors: ['snapshot has no components.schemas — was it generated from app.openapi()?'] };
  }

  for (const [name, expected] of Object.entries(MANIFEST)) {
    const schema = schemas[name];
    if (!schema) {
      errors.push(`${name}: not present in the OpenAPI snapshot (renamed or removed on the backend?)`);
      continue;
    }
    const backendRequired = new Set(schema.required ?? []);
    const backendProps = new Set(Object.keys(schema.properties ?? {}));
    const known = new Set([...expected.required, ...expected.optional]);

    for (const field of expected.required) {
      if (!backendProps.has(field)) errors.push(`${name}.${field}: expected field is gone from the backend schema`);
      else if (!backendRequired.has(field)) errors.push(`${name}.${field}: backend made this optional; mobile code treats it as always-present`);
    }
    for (const field of backendProps) {
      if (!known.has(field)) errors.push(`${name}.${field}: new backend field not declared in contracts.ts or this manifest`);
    }
  }

  return { ok: errors.length === 0, errors };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const { ok, errors } = verifyContracts(getRoot());
  if (!ok) {
    console.error('contract-drift verification FAILED:');
    for (const e of errors) console.error(`  - ${e}`);
    exit(1);
  }
  console.log('contract-drift verification passed');
}
